const RTL_SCRIPT_RE=/[\u0590-\u08FF\uFB1D-\uFDFF\uFE70-\uFEFF]/;
function textDir(text){return RTL_SCRIPT_RE.test(String(text||''))?'rtl':'ltr'}
function projectDir(){return /persian|farsi|arabic|hebrew|urdu|pashto|kurdish|dari/i.test(state.project?.language||'')?'rtl':'ltr'}
const $ = s => document.querySelector(s);
const state = {projects:[], project:null, stories:[], active:1, settings:null, mediaGroups:[], mediaSearchPlan:null, voiceWorkspace:null, voiceConnection:null, narrationWorkspace:null, narrationDraftId:null};
const runUi = {timer:null,startedAt:0,stepTimers:[],finished:true,dismissed:false};
const voiceProcessUi = {operation:null,timer:null,stageTimer:null};
const mediaSearchUi = {busy:false,activeType:'',activeStoryId:'',activeLabel:''};
const providerOptions = [
  ['codex_local','Codex / ChatGPT Subscription'],
  ['claude_local','Claude Code / Claude Subscription'],
  ['openai','OpenAI API'],
  ['anthropic','Anthropic API'],
];

async function api(path, options={}){
  const res = await fetch(path, options);
  const ct = res.headers.get('content-type') || '';
  const data = ct.includes('application/json') ? await res.json() : await res.text();
  if(!res.ok) throw new Error(data?.detail || data || `Request failed (${res.status})`);
  return data;
}
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className=`toast show${error?' error':''}`;clearTimeout(el._t);el._t=setTimeout(()=>el.className='toast',3500)}
function fmtElapsed(ms){const total=Math.max(0,Math.floor(ms/1000));const min=Math.floor(total/60),sec=total%60;return `${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
function renderRunSteps(steps,activeIndex,stateName='running'){const root=$('#runStatus');if(!root)return;root.querySelector('.run-steps').innerHTML=steps.map((label,i)=>{let cls='';if(stateName==='success')cls='done';else if(stateName==='error')cls=i<activeIndex?'done':i===activeIndex?'failed':'';else cls=i<activeIndex?'done':i===activeIndex?'active':'';return `<div class="run-step ${cls}"><i></i><span>${esc(label)}</span></div>`}).join('')}
function startRunStatus({title,meta='',steps=[]}){const root=$('#runStatus');if(!root)return;runUi.stepTimers.forEach(clearTimeout);runUi.stepTimers=[];if(runUi.timer)clearInterval(runUi.timer);runUi.startedAt=Date.now();runUi.finished=false;runUi.dismissed=false;root.className='run-status running';root.innerHTML=`<div class="run-head"><div class="run-identity"><span class="run-spinner"></span><div class="run-copy"><strong id="runTitle">${esc(title)}</strong><span id="runMeta">${esc(meta)}</span></div></div><div class="run-right"><span id="runTime" class="run-time">00:00</span><button type="button" id="runDismiss" class="run-dismiss" title="Dismiss progress (operation continues)">×</button></div></div><div class="run-steps"></div><div id="runError" class="run-error hidden"></div>`;root.dataset.steps=JSON.stringify(steps);root.dataset.active='1';renderRunSteps(steps,1);runUi.timer=setInterval(()=>{const el=$('#runTime');if(el)el.textContent=fmtElapsed(Date.now()-runUi.startedAt)},500);$('#runDismiss').onclick=()=>{runUi.dismissed=true;root.classList.add('hidden')};if(steps.length>2)runUi.stepTimers.push(setTimeout(()=>{if(runUi.finished)return;root.dataset.active='2';renderRunSteps(steps,2)},3500));if(steps.length>3)runUi.stepTimers.push(setTimeout(()=>{if(runUi.finished)return;root.dataset.active='3';renderRunSteps(steps,3)},9000))}
function finishRunStatus(ok,detail='',successTitle='Completed'){const root=$('#runStatus');if(!root)return;runUi.finished=true;runUi.stepTimers.forEach(clearTimeout);runUi.stepTimers=[];if(runUi.timer)clearInterval(runUi.timer);runUi.timer=null;const steps=JSON.parse(root.dataset.steps||'[]');const active=Number(root.dataset.active||Math.max(0,steps.length-1));root.className=`run-status ${ok?'success':'error'}${runUi.dismissed?' hidden':''}`;$('#runTitle').textContent=ok?successTitle:`${$('#runTitle').textContent} failed`;renderRunSteps(steps,ok?steps.length:active,ok?'success':'error');$('#runTime').textContent=fmtElapsed(Date.now()-runUi.startedAt);const err=$('#runError');err.classList.toggle('hidden',ok||!detail);err.textContent=ok?'':detail;$('#runDismiss').onclick=()=>{runUi.dismissed=true;root.classList.add('hidden')}}function finishRunStatusWarning(detail='',title='No suitable B-roll found'){const root=$('#runStatus');if(!root)return;runUi.finished=true;runUi.stepTimers.forEach(clearTimeout);runUi.stepTimers=[];if(runUi.timer)clearInterval(runUi.timer);runUi.timer=null;const steps=JSON.parse(root.dataset.steps||'[]');root.className=`run-status warning${runUi.dismissed?' hidden':''}`;$('#runTitle').textContent=title;renderRunSteps(steps,steps.length,'success');$('#runTime').textContent=fmtElapsed(Date.now()-runUi.startedAt);const err=$('#runError');err.classList.toggle('hidden',!detail);err.textContent=detail;$('#runDismiss').onclick=()=>{runUi.dismissed=true;root.classList.add('hidden')}}

function mediaSearchButtons(){return [...document.querySelectorAll('#stage #searchMediaBtn,#stage #regenerateAllMediaBtn,#stage [data-search-story-media]')]}
function activeMediaSearchButton(){if(!mediaSearchUi.busy)return null;if(mediaSearchUi.activeType==='story'&&mediaSearchUi.activeStoryId)return document.querySelector(`#stage [data-search-story-media="${mediaSearchUi.activeStoryId}"]`);if(mediaSearchUi.activeType==='all')return $('#regenerateAllMediaBtn');return $('#searchMediaBtn')}
function applyMediaSearchBusyState(){if(!mediaSearchUi.busy)return;mediaSearchButtons().forEach(button=>{if(button.dataset.mediaBusyOriginalLabel===undefined)button.dataset.mediaBusyOriginalLabel=button.textContent;if(button.dataset.mediaBusyOriginalDisabled===undefined)button.dataset.mediaBusyOriginalDisabled=button.disabled?'1':'0';button.disabled=true;button.classList.remove('processing','media-search-active')});const active=activeMediaSearchButton();if(active){active.disabled=true;active.classList.add('processing','media-search-active');active.textContent=mediaSearchUi.activeLabel||'Searching…'}}
function beginMediaSearch({type='missing',storyId='',label='Searching…'}={}){if(mediaSearchUi.busy)return false;mediaSearchUi.busy=true;mediaSearchUi.activeType=type;mediaSearchUi.activeStoryId=storyId;mediaSearchUi.activeLabel=label;applyMediaSearchBusyState();return true}
function endMediaSearch(){mediaSearchUi.busy=false;mediaSearchUi.activeType='';mediaSearchUi.activeStoryId='';mediaSearchUi.activeLabel='';mediaSearchButtons().forEach(button=>{button.classList.remove('processing','media-search-active');if(button.dataset.mediaBusyOriginalLabel!==undefined){button.textContent=button.dataset.mediaBusyOriginalLabel;delete button.dataset.mediaBusyOriginalLabel}if(button.dataset.mediaBusyOriginalDisabled!==undefined){button.disabled=button.dataset.mediaBusyOriginalDisabled==='1';delete button.dataset.mediaBusyOriginalDisabled}})}

function lockVoiceControls(lock){document.querySelectorAll('#stage #prepareVoiceBtn,#stage #generateVoiceBtn,#stage #saveNarratorVoiceBtn,#stage [data-save-voice-performance],#stage [data-generate-voice-take],#stage [data-approve-voice-take]').forEach(el=>{el.disabled=!!lock})}
function renderVoiceOperation(){const panel=$('#voiceProcessPanel');if(!panel)return;const op=voiceProcessUi.operation;panel.classList.toggle('hidden',!op);document.querySelectorAll('.voice-segment.generating').forEach(el=>el.classList.remove('generating'));document.querySelectorAll('[data-generate-voice-take].processing,[data-approve-voice-take].processing').forEach(el=>el.classList.remove('processing'));if(!op){lockVoiceControls(false);return}lockVoiceControls(true);const title=$('#voiceProcessTitle'),detail=$('#voiceProcessDetail'),elapsed=$('#voiceProcessElapsed'),bar=$('#voiceProgressBar'),count=$('#voiceProcessCount'),hint=$('#voiceProcessHint');if(title)title.textContent=op.title||'Working…';if(detail)detail.textContent=op.detail||'';if(elapsed)elapsed.textContent=fmtElapsed(Date.now()-op.startedAt);const total=Number(op.total||0),current=Number(op.current||0);if(bar){bar.classList.toggle('indeterminate',!total);if(total){const pct=Math.max(0,Math.min(100,Math.round((current/total)*100)));bar.style.width=`${pct}%`;bar.style.transform='';if(count)count.textContent=`${current} / ${total} · ${pct}%`}else{bar.style.width='';if(count)count.textContent=op.countText||'Processing…'}}if(hint)hint.textContent=op.hint||'';if(op.segmentId){const seg=document.querySelector(`[data-voice-segment="${op.segmentId}"]`);if(seg)seg.classList.add('generating');const selector=op.kind==='approve'?`[data-approve-voice-take="${op.takeNumber}"][data-segment-id="${op.segmentId}"]`:`[data-generate-voice-take="${op.takeNumber}"][data-segment-id="${op.segmentId}"]`;const button=document.querySelector(selector);if(button){button.classList.add('processing');button.disabled=true;button.dataset.voiceOriginalLabel=button.dataset.voiceOriginalLabel||button.textContent;button.textContent=op.kind==='approve'?'Processing…':'Generating…'}const card=button?.closest('.voice-take');const status=card?.querySelector('.voice-take-head span');if(status)status.textContent=op.kind==='approve'?'Measuring + aligning…':'Generating…'}}
function startVoiceOperation({kind='generate',title='Working…',detail='',hint='',total=0,current=0,segmentId='',takeNumber=0,stages=[]}){endVoiceOperation();voiceProcessUi.operation={kind,title,detail,hint,total,current,segmentId,takeNumber,stages,stageIndex:0,startedAt:Date.now()};renderVoiceOperation();voiceProcessUi.timer=setInterval(renderVoiceOperation,500);if(stages.length>1)voiceProcessUi.stageTimer=setInterval(()=>{const op=voiceProcessUi.operation;if(!op)return;op.stageIndex=(op.stageIndex+1)%op.stages.length;op.detail=op.stages[op.stageIndex];renderVoiceOperation()},4200)}
function updateVoiceOperation(values={}){if(!voiceProcessUi.operation)return;Object.assign(voiceProcessUi.operation,values);renderVoiceOperation()}
function endVoiceOperation(){if(voiceProcessUi.timer)clearInterval(voiceProcessUi.timer);if(voiceProcessUi.stageTimer)clearInterval(voiceProcessUi.stageTimer);voiceProcessUi.timer=null;voiceProcessUi.stageTimer=null;voiceProcessUi.operation=null;document.querySelectorAll('[data-voice-original-label]').forEach(button=>{button.textContent=button.dataset.voiceOriginalLabel;delete button.dataset.voiceOriginalLabel});renderVoiceOperation()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function safeExternalUrl(v){const raw=String(v??'').trim();if(!raw)return '#';try{const u=new URL(raw,window.location.origin);if(u.protocol!=='http:'&&u.protocol!=='https:')return '#';return esc(u.href)}catch{return '#'}}

function fmt(n){return new Intl.NumberFormat().format(n||0)}

function weekDefaults(){const end=new Date();end.setDate(end.getDate()+1);const start=new Date(end);start.setDate(start.getDate()-7);return [start.toISOString().slice(0,10),end.toISOString().slice(0,10)]}

async function init(){bind();fillProviderSelects();await refreshSettings();await refreshProjects()}
function bind(){
  $('#newProjectBtn').onclick=()=>openProject(false);$('#emptyCreateBtn').onclick=()=>openProject(false);$('#editProjectBtn').onclick=()=>openProject(true);$('#projectSelect').onchange=e=>loadProject(e.target.value);$('#projectForm').onsubmit=saveProject;$('#chooseFolderBtn').onclick=chooseFolder;$('#openFolderBtn').onclick=openFolder;$('#settingsBtn').onclick=openSettings;$('#settingsForm').onsubmit=saveSettings;
  document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>document.getElementById(x.dataset.close)?.close());
  document.addEventListener('click',async e=>{
    const step=e.target.closest('.step'); if(step){state.active=Number(step.dataset.step);renderPipeline();await renderStage();return}
    const decision=e.target.closest('[data-decision]'); if(decision){await setDecision(decision.dataset.story,decision.dataset.decision);return}
    const login=e.target.closest('[data-login]'); if(login){await providerLogin(login.dataset.login);return}
    const test=e.target.closest('[data-test]'); if(test){await providerTest(test.dataset.test);return}
    const key=e.target.closest('[data-save-key]'); if(key){await saveApiKey(key.dataset.saveKey);return}
  });
  document.addEventListener('change', async e => {
    const input=e.target.closest('[data-media-select]');
    if(input){await setMediaSelected(input.dataset.mediaSelect,input.checked)}
  });
}
function fillProviderSelects(){const html=providerOptions.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');['#sResearchProvider','#sWriterProvider','#sReviewerProvider'].forEach(id=>$(id).innerHTML=html)}

async function refreshProjects(prefer=null){state.projects=await api('/api/projects');$('#projectSelect').innerHTML=state.projects.length?state.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join(''):'<option>No projects yet</option>';if(!state.projects.length){state.project=null;$('#empty').classList.remove('hidden');$('#workspace').classList.add('hidden');return}const id=prefer||state.project?.id||state.projects[0].id;$('#projectSelect').value=id;await loadProject(id)}
async function loadProject(id){state.project=await api(`/api/projects/${id}`);state.stories=await api(`/api/projects/${id}/stories`);$('#empty').classList.add('hidden');$('#workspace').classList.remove('hidden');$('#openFolderBtn').disabled=false;$('#editProjectBtn').disabled=false;renderProject();renderPipeline();await renderStage()}
function renderProject(){const p=state.project;$('#title').textContent=p.name;$('#subtitle').textContent='Cinema → Weekly News';$('#projectName').textContent=p.name;$('#projectWeek').textContent=`${p.date_start} → ${p.date_end}`;$('#projectLanguage').textContent=p.language;$('#projectDuration').textContent=`${p.target_minutes} min · B-roll chunks ${Number(p.media_chunk_minutes||1)} min`;$('#projectFocus').textContent=`${p.editorial_focus} · ${p.geographic_focus}`}
function renderPipeline(){const items=state.project?.pipeline||[[1,'research','Format Research'],[2,'pick-news','Section Selection'],[3,'narration','Narration Writer'],[4,'voice','Voice'],[5,'media-sources','Media Sources'],[6,'downloads','Downloads'],[7,'resolve-plan','Resolve Plan']];$('#pipeline').innerHTML=items.map(([n,slug,title])=>`<div class="step ${state.active===n?'active':''}" data-step="${n}"><span class="step-num">${String(n).padStart(2,'0')}</span><span>${esc(title)}</span></div>`).join('')}

function openProject(edit){const d=$('#projectDialog');$('#projectDialogTitle').textContent=edit?'Edit Project':'New Project';$('#folderField').classList.toggle('hidden',edit);d.dataset.edit=edit?'1':'0';if(edit&&state.project){const p=state.project;$('#pName').value=p.name;$('#pStart').value=p.date_start;$('#pEnd').value=p.date_end;$('#pLanguage').value=p.language;$('#pDuration').value=p.target_minutes;$('#pMediaChunk').value=Number(p.media_chunk_minutes||1);$('#pGeo').value=p.geographic_focus;$('#pFocus').value=p.editorial_focus;$('#pNotes').value=p.notes||'';$('#pChannelName').value=p.channel_name||''}else{$('#projectForm').reset();const [s,e]=weekDefaults();$('#pStart').value=s;$('#pEnd').value=e;$('#pLanguage').value='Persian';$('#pDuration').value=15;$('#pMediaChunk').value=1;$('#pGeo').value='Worldwide';$('#pFocus').value='Balanced';$('#pParent').value=''}d.showModal()}
async function chooseFolder(){try{const r=await api('/api/system/pick-folder',{method:'POST'});if(!r.cancelled)$('#pParent').value=r.path}catch(e){toast(e.message,true)}}
async function saveProject(e){e.preventDefault();const edit=$('#projectDialog').dataset.edit==='1';const body={name:$('#pName').value.trim(),channel:'cinema',content_type:'weekly_news',language:$('#pLanguage').value.trim()||'Persian',target_minutes:Number($('#pDuration').value||15),media_chunk_minutes:Number($('#pMediaChunk').value||1),date_start:$('#pStart').value,date_end:$('#pEnd').value,geographic_focus:$('#pGeo').value.trim()||'Worldwide',editorial_focus:$('#pFocus').value,notes:$('#pNotes').value.trim(),channel_name:$('#pChannelName').value.trim()};try{let p;if(edit){p=await api(`/api/projects/${state.project.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}else{body.parent_path=$('#pParent').value;if(!body.parent_path)throw new Error('Choose a project folder first.');p=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}$('#projectDialog').close();await refreshProjects(p.id);toast(edit?'Project updated':'Project created')}catch(err){toast(err.message,true)}}
async function openFolder(){if(!state.project)return;try{await api(`/api/projects/${state.project.id}/open-folder`,{method:'POST'})}catch(e){toast(e.message,true)}}

async function renderStage(){if(!state.project)return;const stage=$('#stage');if(state.active===1)stage.innerHTML=researchHtml();else if(state.active===2)stage.innerHTML=pickerHtml();else if(state.active===3){stage.innerHTML=await narrationHtml()}else if(state.active===4){stage.innerHTML=await voiceHtml()}else if(state.active===5){stage.innerHTML=await mediaPlanHtml()}else if(state.active===6){stage.innerHTML=await findMediaHtml()}else{stage.innerHTML=await resolvePlanHtml()}wireStage()}
function wireStage(){const r=$('#runResearchBtn');if(r)r.onclick=runResearch;const n=$('#generateNarrationBtn');if(n)n.onclick=generateNarration;const vc=$('#connectElevenBtn');if(vc)vc.onclick=connectElevenLabs;const vs=$('#saveNarratorVoiceBtn');if(vs)vs.onclick=saveNarratorVoice;const vp=$('#prepareVoiceBtn');if(vp)vp.onclick=prepareVoice;const vg=$('#generateVoiceBtn');if(vg)vg.onclick=generateVoice;document.querySelectorAll('[data-save-voice-performance]').forEach(b=>b.onclick=()=>saveVoicePerformance(b.dataset.saveVoicePerformance));document.querySelectorAll('[data-generate-voice-take]').forEach(b=>b.onclick=()=>generateVoiceTake(b.dataset.segmentId,Number(b.dataset.generateVoiceTake)));document.querySelectorAll('[data-approve-voice-take]').forEach(b=>b.onclick=()=>approveVoiceTake(b.dataset.segmentId,Number(b.dataset.approveVoiceTake)));const m=$('#searchMediaBtn');if(m)m.onclick=()=>searchMedia('missing');const ma=$('#regenerateAllMediaBtn');if(ma)ma.onclick=()=>searchMedia('all');document.querySelectorAll('[data-search-story-media]').forEach(b=>b.onclick=()=>searchSingleStoryMedia(b.dataset.searchStoryMedia));const d=$('#downloadSelectedBtn');if(d)d.onclick=downloadSelectedMedia;const rg=$('#generateResolveBtn');if(rg)rg.onclick=generateResolvePlan;const ro=$('#openResolveFolderBtn');if(ro)ro.onclick=openResolveFolder;renderVoiceOperation();applyMediaSearchBusyState()}
function metrics(){const c=state.project.counts||{};return `<div class="research-summary"><div class="metric card"><span>${fmt(c.articles)}</span><small>articles/posts found</small></div><div class="metric card"><span>${fmt(c.stories)}</span><small>unique stories</small></div><div class="metric card"><span>${fmt(c.included)}</span><small>included</small></div><div class="metric card"><span>${fmt(c.narrations)}</span><small>narration versions</small></div></div>`}
function researchHtml(){return `<div class="section-head"><div><div class="eyebrow">STEP 01</div><h2>Research the week</h2><p>Search the selected date range across cinema-news query groups, deduplicate repeated coverage, and optionally let your selected AI provider rank what deserves attention.</p></div><button id="runResearchBtn" class="btn primary">Run Weekly Research</button></div>${metrics()}${state.stories.length?`<div class="run-note">Latest research is loaded below. AI ranking is advisory; you make the final Include / Maybe / Skip decision.</div><div style="height:12px"></div>${storyCards(state.stories.slice(0,30))}`:`<div class="card placeholder">No research run yet. Run research for ${esc(state.project.date_start)} → ${esc(state.project.date_end)}.</div>`}`}
function pickerHtml(){const include=state.stories.filter(s=>s.decision==='include'),maybe=state.stories.filter(s=>s.decision==='maybe'),skip=state.stories.filter(s=>s.decision==='skip');return `<div class="section-head"><div><div class="eyebrow">STEP 02</div><h2>Pick the stories</h2><p>AI can recommend, but this screen is the editorial gate. Only <strong>Include</strong> stories are sent to narration.</p></div></div>${metrics()}<div class="toolbar"><span class="pill">Include ${include.length}</span><span class="pill">Maybe ${maybe.length}</span><span class="pill">Skip ${skip.length}</span></div>${state.stories.length?storyCards(state.stories):'<div class="card placeholder">Run research first.</div>'}`}
function storyCards(stories){return `<div class="story-list">${stories.map(s=>`<article class="story-card card"><div class="story-head"><div><div class="story-title">${esc(s.canonical_title)}</div><div class="story-meta"><span class="pill">${esc(s.category.replaceAll('_',' '))}</span><span class="signal ${s.attention}">Attention ${esc(s.attention)}</span><span class="signal ${s.importance}">Importance ${esc(s.importance)}</span><span class="signal">${esc(s.confidence)}</span><span class="signal">Visuals ${esc(s.visual_potential)}</span><span class="signal">${s.source_count} source${s.source_count===1?'':'s'}</span></div></div><div class="score">${Number(s.score).toFixed(1)}</div></div>${s.summary?`<div class="story-summary">${esc(s.summary)}</div>`:''}<div class="story-rationale">${esc(s.rationale)}</div><div class="decision"><button class="btn ghost ${s.decision==='include'?'active include':''}" data-story="${s.id}" data-decision="include">Include</button><button class="btn ghost ${s.decision==='maybe'?'active maybe':''}" data-story="${s.id}" data-decision="maybe">Maybe</button><button class="btn ghost ${s.decision==='skip'?'active skip':''}" data-story="${s.id}" data-decision="skip">Skip</button></div><div class="source-links"><details><summary>Sources (${s.articles.length})</summary>${s.articles.map(a=>`<a href="${safeExternalUrl(a.url)}" target="_blank" rel="noreferrer">${esc(a.source||'Source')} — ${esc(a.title)}</a>`).join('')}</details></div></article>`).join('')}</div>`}
async function setDecision(id,decision){try{await api(`/api/projects/${state.project.id}/stories/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision})});const s=state.stories.find(x=>x.id===id);if(s)s.decision=decision;state.project=await api(`/api/projects/${state.project.id}`);await renderStage()}catch(e){toast(e.message,true)}}
async function runResearch(){const b=$('#runResearchBtn');b.disabled=true;b.textContent='Researching…';startRunStatus({title:'Researching weekly cinema news',meta:`${state.project.date_start} → ${state.project.date_end}`,steps:['Request sent','Searching sources','Clustering + ranking','Results saved']});try{const s=state.settings?.ai||{};const r=await api(`/api/projects/${state.project.id}/research`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:s.research_provider,model:s.research_model,ai_rank:true})});state.project=await api(`/api/projects/${state.project.id}`);state.stories=await api(`/api/projects/${state.project.id}/stories`);await renderStage();finishRunStatus(true,'','Research complete and saved');toast(r.ai_rank_error?`Research complete; AI ranking unavailable, heuristic ranking used: ${r.ai_rank_error}`:`Research complete: ${r.article_count} articles → ${r.story_count} stories`,!!r.ai_rank_error)}catch(e){finishRunStatus(false,e.message);toast(e.message,true);b.disabled=false;b.textContent='Run Weekly Research'}}

async function narrationHtml(){let list=[];try{list=await api(`/api/projects/${state.project.id}/narrations`)}catch{}const latest=list[0];return `<div class="section-head"><div><div class="eyebrow">STEP 03</div><h2>Generate narration</h2><p>Only Included stories are supplied to the writer. The output keeps STORY IDs so every paragraph can be traced into the media plan.</p></div><button id="generateNarrationBtn" class="btn primary">Generate Narration</button></div>${metrics()}${latest?`<div class="run-note">Latest: v${latest.version_number} · ${esc(latest.provider)} / ${esc(latest.model)}</div><div style="height:12px"></div><pre class="editor">${esc(latest.content)}</pre>`:'<div class="card placeholder">Include stories in Step 2, then generate the narration.</div>'}`}
async function generateNarration(){const b=$('#generateNarrationBtn');b.disabled=true;b.textContent='Writing…';const s=state.settings?.ai||{};startRunStatus({title:'Generating narration',meta:`${s.writer_provider||'writer'} · ${s.writer_model||'default'}`,steps:['Request sent','AI writing','Validating story coverage','Narration saved']});try{await api(`/api/projects/${state.project.id}/narration`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:s.writer_provider,model:s.writer_model})});state.project=await api(`/api/projects/${state.project.id}`);await renderStage();finishRunStatus(true,'','Narration generated and saved');toast('Narration generated')}catch(e){finishRunStatus(false,e.message);toast(e.message,true);b.disabled=false;b.textContent='Generate Narration'}}

function voiceTime(sec){sec=Number(sec||0);const m=Math.floor(sec/60),s=Math.floor(sec%60);return `${m}:${String(s).padStart(2,'0')}`}
function storyTitleForVoice(id){return state.stories.find(x=>x.id===id)?.canonical_title||id||'Intro / transition / outro'}
async function loadVoiceWorkspace(){try{const [connection,workspace]=await Promise.all([api('/api/voice/connection'),api(`/api/projects/${state.project.id}/voice`)]);state.voiceConnection=connection;state.voiceWorkspace=workspace}catch(e){state.voiceConnection={configured:false,connected:false,voices:[],error:e.message};state.voiceWorkspace=null}return state.voiceWorkspace}
async function voiceHtml(){const w=await loadVoiceWorkspace();const pron=await loadPronunciations();const conn=state.voiceConnection||{};if(!w?.narration)return `<div class="section-head"><div><div class="eyebrow">STEP 04</div><h2>Narrator voice</h2><p>Generate the narration first. This step uses one ElevenLabs narrator voice for the entire episode.</p></div></div><div class="card placeholder">Generate narration in Step 3 first.</div>`;
const configured=conn.connected;const voices=conn.voices||[];const selected=w.settings?.voice_id||'';const voiceOptions=voices.map(v=>`<option value="${esc(v.voice_id)}" ${v.voice_id===selected?'selected':''}>${esc(v.name)}${v.category?` · ${esc(v.category)}`:''}</option>`).join('');const prepared=w.segments?.length||0;const generated=w.generated_count||0;const aligned=w.aligned_count||0;const total=w.total_duration_seconds||0;
const connection=`<section class="voice-config card"><div class="voice-config-head"><div><div class="eyebrow">ELEVENLABS</div><h3>${configured?'Connected ✓':'Connect ElevenLabs'}</h3><p>${configured?`${voices.length} account voices available · Eleven v3`:'Use your ElevenLabs API key. It is stored in the OS credential store, not the project.'}</p></div></div>${configured?`<div class="voice-picker-row"><label>One narrator voice for the whole episode<select id="narratorVoiceSelect"><option value="">Choose narrator voice…</option>${voiceOptions}</select></label><button id="saveNarratorVoiceBtn" class="btn secondary">Use This Voice</button></div>${conn.error?`<div class="run-note warn">${esc(conn.error)}</div>`:''}`:`<div class="voice-connect-row"><input id="elevenApiKey" type="password" placeholder="ElevenLabs API key" /><button id="connectElevenBtn" class="btn primary">Connect</button></div>${conn.error?`<div class="run-note warn">${esc(conn.error)}</div>`:''}`}</section>`;
const durationRows=Object.entries(w.story_durations||{}).sort((a,b)=>b[1].duration_seconds-a[1].duration_seconds).map(([id,x])=>`<div class="voice-story-time"><strong>${esc(storyTitleForVoice(id))}</strong><span>${voiceTime(x.duration_seconds)} · ${x.segment_count} segment${x.segment_count===1?'':'s'}</span></div>`).join('');
const segments=(w.segments||[]).map(seg=>{const approved=seg.approval_status==='approved'&&Number(seg.selected_take)>0;const take=(n)=>{const path=n===1?seg.take1_path:seg.take2_path;const ok=approved&&Number(seg.selected_take)===n;return `<div class="voice-take ${ok?'approved':''}"><div class="voice-take-head"><strong>Take ${n}</strong><span>${ok?'Approved ✓':path?'Generated':'Not generated'}</span></div>${path?`<audio controls preload="none" src="/api/projects/${state.project.id}/voice/${seg.id}/takes/${n}/audio"></audio>`:'<div class="voice-take-empty">Generate this take to listen.</div>'}<div class="voice-take-actions"><button class="btn ghost small-link" data-generate-voice-take="${n}" data-segment-id="${seg.id}">${path?'Regenerate':'Generate'} Take ${n}</button>${path&&!ok?`<button class="btn secondary small-link" data-approve-voice-take="${n}" data-segment-id="${seg.id}">Approve Take ${n}</button>`:''}</div></div>`};return `<article class="voice-segment card" data-voice-segment="${seg.id}"><div class="voice-segment-head"><div><span class="pill">#${String(seg.segment_index).padStart(3,'0')}</span><strong>${esc(storyTitleForVoice(seg.story_id))}</strong></div><span class="signal ${approved?'high':''}">${approved?`Take ${seg.selected_take} approved ✓`:'Needs approved take'}${seg.duration_seconds?` · ${voiceTime(seg.duration_seconds)}`:''}</span></div><div class="voice-text-grid"><div class="voice-text-box"><small>EXACT SPOKEN TEXT · LOCKED</small><p class="voice-source-text" dir="${projectDir()}">${esc(seg.source_text)}</p></div><div class="voice-text-box"><small>ELEVEN V3 PERFORMANCE INPUT · EDITABLE</small><textarea dir="${projectDir()}" class="voice-performance-editor" data-performance-editor="${seg.id}">${esc(seg.performance_text||seg.source_text)}</textarea><div class="voice-performance-actions"><button class="btn ghost small-link" data-save-voice-performance="${seg.id}">Save Performance Input</button><span>Spoken words/order stay locked.</span></div></div></div><div class="voice-takes">${take(1)}${take(2)}</div></article>`}).join('');
return `<div class="section-head"><div><div class="eyebrow">STEP 04</div><h2>Voices · one segment at a time</h2><p>One narrator voice for the whole episode, generated one segment at a time. Listen to Take 1 or Take 2 and approve one take per segment.</p></div></div>${w.voice_status?.stale?`<div class="run-note warn voice-stale">⚠ ${esc(w.voice_status.message)}</div>`:''}${connection}${pronunciationCardHtml(pron)}<div class="research-summary voice-metrics"><div class="metric card"><span>${prepared}</span><small>prepared chunks</small></div><div class="metric card"><span>${generated}</span><small>generated</small></div><div class="metric card"><span>${aligned}</span><small>aligned</small></div><div class="metric card"><span>${voiceTime(total)}</span><small>real narration duration</small></div></div><div class="voice-actions"><button id="prepareVoiceBtn" class="btn secondary" ${selected?'':'disabled'}>Prepare v3 Performance</button><button id="generateVoiceBtn" class="btn primary" ${prepared&&selected&&configured?'':'disabled'}>Generate Missing Take 1s</button></div><div id="voiceProcessPanel" class="voice-process hidden"><div class="voice-process-head"><div class="voice-spinner"></div><div class="voice-process-copy"><strong id="voiceProcessTitle">Working…</strong><span id="voiceProcessDetail"></span></div><span id="voiceProcessElapsed" class="voice-process-time">00:00</span></div><div class="voice-progress-track"><div id="voiceProgressBar" class="voice-progress-bar indeterminate"></div></div><div class="voice-process-foot"><span id="voiceProcessCount" class="voice-process-count"></span><span id="voiceProcessHint"></span></div></div><div class="run-note">Generate All sends segments to ElevenLabs one at a time (#001, then #002, …) and saves each before the next. Take 2 is an optional second API generation. Approving a take measures its real MP3 duration and forced-aligns its words for Media and Resolve.</div>${durationRows?`<div class="voice-story-times"><div class="media-kind-title">News narration durations</div>${durationRows}</div>`:''}<div class="voice-segment-list">${segments||'<div class="card placeholder">Choose a voice, then prepare the narration.</div>'}</div>`}
async function connectElevenLabs(){const input=$('#elevenApiKey');const key=input?.value.trim();if(!key)return toast('Paste your ElevenLabs API key first',true);startRunStatus({title:'Connecting ElevenLabs',meta:'Validating key + loading account voices',steps:['Key received','Checking account','Loading voices','Connected']});try{await api('/api/voice/connection',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({api_key:key})});await renderStage();finishRunStatus(true,'','ElevenLabs connected');toast('ElevenLabs connected')}catch(e){finishRunStatus(false,e.message);toast(e.message,true)}}
async function saveNarratorVoice(){const select=$('#narratorVoiceSelect');const voice_id=select?.value;if(!voice_id)return toast('Choose a narrator voice first',true);const voice_name=select.options?.[select.selectedIndex]?.textContent?.split(' · ')[0]||'';try{await api(`/api/projects/${state.project.id}/voice/settings`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({voice_id,voice_name})});await renderStage();toast(`Narrator voice set to ${voice_name}`)}catch(e){toast(e.message,true)}}
async function prepareVoice(){const b=$('#prepareVoiceBtn');if(b)b.disabled=true;startRunStatus({title:'Preparing Eleven v3 narration',meta:'One narrator · continuity-aware performance',steps:['Extracting STORY narration','Directing performance','Safety validating words','Voice chunks saved']});try{const r=await api(`/api/projects/${state.project.id}/voice/prepare`,{method:'POST'});state.project=await api(`/api/projects/${state.project.id}`);await renderStage();finishRunStatus(true,'','Voice performance prepared');toast((r.warnings||[]).length?`Prepared with ${r.warnings.length} warning(s)`:`Prepared ${r.segments?.length||0} voice chunks`)}catch(e){finishRunStatus(false,e.message);toast(e.message,true)}}
async function saveVoicePerformance(id){const editor=document.querySelector(`[data-performance-editor="${id}"]`);const performance_text=editor?.value.trim();if(!performance_text)return toast('Performance input cannot be empty',true);try{const r=await api(`/api/projects/${state.project.id}/voice/${id}/performance`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({performance_text})});await renderStage();toast(r.changed?'Performance input saved; previous takes cleared':'Performance input unchanged')}catch(e){toast(e.message,true)}}
async function generateVoiceTake(id,take){const seg=(state.voiceWorkspace?.segments||[]).find(x=>x.id===id);if(!seg)return;const existing=take===1?seg.take1_path:seg.take2_path;if(existing&&!confirm(`Regenerate Take ${take}? This is another ElevenLabs API generation and may use additional credits.`))return;if(take===2&&!existing&&!confirm('Generate Take 2? This is a second ElevenLabs API generation and may use additional credits.'))return;startRunStatus({title:`Generating Take ${take}`,meta:`Segment #${String(seg.segment_index).padStart(3,'0')} · only this segment`,steps:['Sending one segment','Eleven v3 generating','Saving MP3','Take ready']});startVoiceOperation({kind:'generate',title:`Generating Take ${take}`,detail:`Segment #${String(seg.segment_index).padStart(3,'0')} · sending to ElevenLabs`,hint:'This can take a little while. Keep this page open.',total:1,current:0,segmentId:id,takeNumber:take,stages:['Sending segment to ElevenLabs…','Eleven v3 is generating the voice…','Receiving and saving the MP3…']});try{await api(`/api/projects/${state.project.id}/voice/${id}/takes/${take}/generate`,{method:'POST'});updateVoiceOperation({current:1,detail:'MP3 saved · refreshing voice segment…'});endVoiceOperation();await renderStage();finishRunStatus(true,'',`Take ${take} generated`);toast(`Take ${take} generated`)}catch(e){endVoiceOperation();finishRunStatus(false,e.message);toast(e.message,true)}}
async function approveVoiceTake(id,take){const seg=(state.voiceWorkspace?.segments||[]).find(x=>x.id===id);startRunStatus({title:`Approving Take ${take}`,meta:`Segment #${String(seg?.segment_index||0).padStart(3,'0')} · exact duration + forced alignment`,steps:['Selecting take','Measuring MP3','Aligning words','Timing saved']});startVoiceOperation({kind:'approve',title:`Processing Take ${take}`,detail:`Segment #${String(seg?.segment_index||0).padStart(3,'0')} · measuring real MP3 duration`,hint:'Approval runs ElevenLabs forced alignment before timing is saved.',total:1,current:0,segmentId:id,takeNumber:take,stages:['Measuring the approved MP3…','Running ElevenLabs forced alignment…','Saving exact word timing…']});try{await api(`/api/projects/${state.project.id}/voice/${id}/takes/${take}/approve`,{method:'POST'});updateVoiceOperation({current:1,detail:'Timing saved · refreshing voice segment…'});endVoiceOperation();state.project=await api(`/api/projects/${state.project.id}`);await renderStage();finishRunStatus(true,'',`Take ${take} approved`);toast(`Take ${take} approved and aligned`)}catch(e){endVoiceOperation();finishRunStatus(false,e.message);toast(e.message,true)}}
async function generateVoice(){const all=state.voiceWorkspace?.segments||[];const pending=all.filter(x=>x.approval_status!=='approved'&&!x.take1_path);if(!pending.length)return toast('Every segment already has Take 1 or an approved take');if(!confirm(`Generate Take 1 for ${pending.length} missing segment(s), one by one? Each segment is a separate ElevenLabs API generation.`))return;startRunStatus({title:'Generating missing first takes',meta:`0 / ${pending.length} · one segment per request`,steps:['Starting sequence','Generating one by one','Saving each MP3','First takes complete']});startVoiceOperation({kind:'generate',title:'Generating missing Take 1s',detail:'Starting ElevenLabs sequence…',hint:'Each narration segment is generated and saved separately.',total:pending.length,current:0,stages:['Sending the current segment to ElevenLabs…','Eleven v3 is generating the current voice…','Saving the current MP3 before continuing…']});let completed=0;try{for(const seg of pending){const label=`#${String(seg.segment_index).padStart(3,'0')}`;const meta=$('#runMeta');if(meta)meta.textContent=`${completed} / ${pending.length} · generating ${label}`;updateVoiceOperation({current:completed,segmentId:seg.id,takeNumber:1,detail:`${label} · generating Take 1 with ElevenLabs…`});await api(`/api/projects/${state.project.id}/voice/${seg.id}/takes/1/generate`,{method:'POST'});completed++;updateVoiceOperation({current:completed,detail:`${label} saved · moving to next segment…`});if(meta)meta.textContent=`${completed} / ${pending.length} generated`;}endVoiceOperation();state.project=await api(`/api/projects/${state.project.id}`);await renderStage();finishRunStatus(true,'','Missing Take 1s generated');toast(`Generated ${completed} first take(s) one by one`)}catch(e){endVoiceOperation();state.project=await api(`/api/projects/${state.project.id}`);await renderStage();finishRunStatus(false,`Stopped after ${completed} of ${pending.length}: ${e.message}`);toast(`Generation stopped after ${completed} of ${pending.length}: ${e.message}`,true)}}

async function loadMediaGroups(){try{state.mediaGroups=await api(`/api/projects/${state.project.id}/media/candidates`)}catch{state.mediaGroups=[]}return state.mediaGroups}
async function loadMediaSearchPlan(){try{state.mediaSearchPlan=await api(`/api/projects/${state.project.id}/media/search-plan`)}catch{state.mediaSearchPlan=null}return state.mediaSearchPlan}
async function mediaPlanHtml(){const [groups,plan]=await Promise.all([loadMediaGroups(),loadMediaSearchPlan()]);const missingGroups=groups.filter(g=>!(g.candidates||[]).length);const vc=state.project.counts||{};const voiceReady=Number(vc.voice_segments||0)>0&&Number(vc.voice_aligned||0)===Number(vc.voice_segments||0);const chunks=Number(plan?.total_chunks||0);const chunkMinutes=Number(plan?.chunk_minutes||state.project.media_chunk_minutes||1);const actualMinutes=Number(plan?.actual_story_voice_seconds||0)/60;return `<div class="section-head"><div><div class="eyebrow">STEP 05</div><h2>Videos & supporting images for Included news</h2><p>Every Included story gathers acceptable official/original video copies from YouTube, the news/reference pages, and other supported video sources, then ranks them globally by quality. For the same trailer/clip, 4K wins over 1440p/1080p/720p; source/originality is the tiebreaker. If current-title footage is unavailable, the app automatically tries contextual cast/director footage and official previous-installment/franchise B-roll before falling back to images.</p></div><div class="top-actions"><button id="searchMediaBtn" class="btn primary" ${voiceReady&&missingGroups.length?'':'disabled'}>Search Missing (${missingGroups.length})</button><button id="regenerateAllMediaBtn" class="btn secondary" ${voiceReady?'':'disabled'}>Regenerate All</button></div></div>${voiceReady?'':`<div class="run-note warn">Approve one take for every narration segment in Step 4 first. Media selection uses the real ElevenLabs duration for every news item.</div>`}<div class="media-chunk-summary card"><div><strong>${chunkMinutes} min</strong><span>internal search chunk</span></div><div><strong>${chunks}</strong><span>requests when running all</span></div><div><strong>${actualMinutes.toFixed(1)} min</strong><span>story narration</span></div><div><button class="btn ghost small-link" type="button" onclick="openProject(true)">Change in Project Settings</button></div></div><div class="run-note"><strong>Search Missing</strong> searches only stories with 0 results. <strong>Regenerate All</strong> reruns all Included stories using the configured chunk size internally. Each story below has its own Generate/Regenerate B-roll button.</div><div style="height:12px"></div><div id="mediaResults">${groups.length?renderMediaGroups(groups,false):'<div class="card placeholder">Include stories in Step 2, then search for B-roll.</div>'}</div>`}

function mediaChunksForStoryIds(plan,storyIds){const wanted=new Set(storyIds||[]);const chunks=[];for(const chunk of plan?.chunks||[]){const ids=(chunk.story_ids||[]).filter(id=>wanted.has(id));if(!ids.length)continue;chunks.push({...chunk,story_ids:ids,story_count:ids.length})}return chunks}

async function runMediaChunks(chunks,{refresh=true,title='Finding official B-roll',totalStoryCount=null}={}){if(!chunks.length)return {added:0,stories:0,storiesWithResults:0,storiesWithoutResults:0,errors:0,failures:[],diagnostics:[]};startRunStatus({title,meta:`0 / ${chunks.length} chunks`,steps:['Planning chunks','Gathering video sources','Comparing 4K / HD copies','Saving each chunk']});let totalAdded=0,totalStories=0,totalWithResults=0,totalWithoutResults=0,totalErrors=0;const failures=[],diagnostics=[];for(let i=0;i<chunks.length;i++){const chunk=chunks[i];const meta=$('#runMeta');const label=`Chunk ${i+1}/${chunks.length} · ${voiceTime(chunk.duration_seconds)} narration · ${chunk.story_count} stor${chunk.story_count===1?'y':'ies'}`;if(meta)meta.textContent=label;try{const result=await api(`/api/projects/${state.project.id}/media/search`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh,max_images_per_story:8,max_videos_per_story:8,story_ids:chunk.story_ids})});totalAdded+=Number(result.added||0);totalStories+=Number(result.stories||0);totalWithResults+=Number(result.stories_with_results||0);totalWithoutResults+=Number(result.stories_without_results||0);const chunkDiagnostics=result.diagnostics||[];diagnostics.push(...chunkDiagnostics);totalErrors+=chunkDiagnostics.reduce((n,x)=>n+(x.errors||[]).length,0);await loadMediaGroups();const results=$('#mediaResults');if(results){results.innerHTML=renderMediaGroups(state.mediaGroups,false);wireStage()}if(meta){const foundText=Number(result.stories_with_results||0)>0?` · ${result.stories_with_results} with results`:` · no suitable media found`;meta.textContent=`Chunk ${i+1}/${chunks.length} saved · ${totalStories}/${totalStoryCount||chunks.reduce((n,x)=>n+x.story_count,0)} stories complete${foundText}`}}catch(e){failures.push(`Chunk ${i+1}: ${e.message}`);if(meta)meta.textContent=`Chunk ${i+1}/${chunks.length} failed · continuing…`}}return {added:totalAdded,stories:totalStories,storiesWithResults:totalWithResults,storiesWithoutResults:totalWithoutResults,errors:totalErrors,failures,diagnostics}}

async function searchMedia(mode='missing'){if(mediaSearchUi.busy)return;let storyIds=[];if(mode==='all'){storyIds=(state.mediaGroups||[]).map(g=>g.story.id)}else{storyIds=(state.mediaGroups||[]).filter(g=>!(g.candidates||[]).length).map(g=>g.story.id)}if(!storyIds.length){toast(mode==='all'?'No Included stories to regenerate.':'No missing stories. Every story already has media results.');return}const type=mode==='all'?'all':'missing';const label=mode==='all'?'Regenerating…':'Searching…';if(!beginMediaSearch({type,label}))return;let runStarted=false;try{const plan=await api(`/api/projects/${state.project.id}/media/search-plan`);const chunks=mediaChunksForStoryIds(plan,storyIds);if(!chunks.length)throw new Error('Could not create B-roll search chunks.');runStarted=true;const result=await runMediaChunks(chunks,{refresh:true,title:mode==='all'?'Regenerating all B-roll':'Searching missing B-roll',totalStoryCount:storyIds.length});state.project=await api(`/api/projects/${state.project.id}`);if(result.failures.length){finishRunStatus(false,`Completed ${chunks.length-result.failures.length}/${chunks.length} chunks. ${result.failures.join(' | ')}`);toast(`Saved ${chunks.length-result.failures.length} chunk(s); ${result.failures.length} failed.`,true)}else if(result.storiesWithoutResults>0){finishRunStatusWarning(`${result.storiesWithResults} stor${result.storiesWithResults===1?'y':'ies'} now have media; ${result.storiesWithoutResults} still have no suitable result.`,mode==='all'?'B-roll regeneration finished with missing media':'Missing B-roll search finished');toast(`${result.storiesWithoutResults} stor${result.storiesWithoutResults===1?'y':'ies'} still have no suitable B-roll.`,true)}else{finishRunStatus(true,'',mode==='all'?'All B-roll regenerated':'Missing B-roll search complete');toast(result.errors?`Added ${result.added} candidates; ${result.errors} source checks reported an issue.`:`Added ${result.added} candidates for ${result.stories} stories`)}}catch(e){if(runStarted)finishRunStatus(false,e.message);toast(e.message,true)}finally{endMediaSearch();if(state.active===5)await renderStage()}}

async function searchSingleStoryMedia(storyId){if(mediaSearchUi.busy)return;const group=(state.mediaGroups||[]).find(g=>g.story.id===storyId);if(!group)return;const hasResults=(group.candidates||[]).length>0;if(hasResults&&!confirm('Regenerate B-roll for this story? Downloaded files will be preserved; other un-downloaded results for this story may be replaced.'))return;const activeLabel=hasResults?'Regenerating…':'Searching…';if(!beginMediaSearch({type:'story',storyId,label:activeLabel}))return;let runStarted=false;try{const plan=state.mediaSearchPlan||await loadMediaSearchPlan();const chunks=mediaChunksForStoryIds(plan,[storyId]);if(!chunks.length)throw new Error('Could not create a search chunk for this story.');runStarted=true;const result=await runMediaChunks(chunks,{refresh:true,title:hasResults?'Regenerating story B-roll':'Finding story B-roll',totalStoryCount:1});state.project=await api(`/api/projects/${state.project.id}`);if(result.failures.length){finishRunStatus(false,result.failures.join(' | '));toast(result.failures[0],true)}else if(result.storiesWithResults===0){const diag=result.diagnostics[0]||{};const detail=(diag.errors||[]).length?`Search finished with no accepted media. Source checks: ${diag.errors.slice(0,2).join(' | ')}`:'Search finished successfully, but no video or fallback image passed the relevance/source filters. You can retry after the source/search improvements or open the news source to verify the asset.';finishRunStatusWarning(detail,'No suitable B-roll found');toast('Search finished, but no suitable B-roll was found for this story.',true)}else{finishRunStatus(true,'',hasResults?'Story B-roll regenerated':'Story B-roll found');toast(`Saved ${result.added} new candidate(s)`)}}catch(e){if(runStarted)finishRunStatus(false,e.message);toast(e.message,true)}finally{endMediaSearch();if(state.active===5)await renderStage()}}
function mediaCoveragePlanHtml(story){const plan=story.visual_coverage||{};const count=Number(plan.target_count||1);const beats=plan.beats||[];const chips=beats.map(x=>{const label=x.label||'';if(!label)return '';const kind=String(x.kind||'title').replaceAll('_',' ');const layout=x.layout_hint&&x.layout_hint!=='single'?` · ${String(x.layout_hint).replaceAll('_',' ')}`:'';return `<span class="visual-plan-chip"><strong>${esc(label)}</strong><small>${esc(kind+layout)}</small></span>`}).join('');return `<div class="story-coverage-plan"><strong>${count} narration-aware visual beat${count===1?'':'s'} recommended</strong>${chips?`<div class="visual-plan-chips">${chips}</div>`:''}</div>`}
function renderMediaGroups(groups,selectedOnly){return `<div class="media-story-list">${groups.map(group=>{const all=group.candidates||[];const candidates=selectedOnly?all.filter(x=>x.selected):all;if(selectedOnly&&!candidates.length)return '';const images=candidates.filter(x=>x.media_type==='image');const videos=candidates.filter(x=>x.media_type==='video');return `<section class="media-story card"><div class="media-story-head"><div><div class="eyebrow">${esc((group.story.category||'').replaceAll('_',' '))}</div><h3>${esc(group.story.title)}</h3><div class="story-meta-row">${group.story.voice_duration_seconds?`<div class="story-voice-duration">Narration ${voiceTime(group.story.voice_duration_seconds)}</div>`:''}${mediaCoveragePlanHtml(group.story)}</div></div><div class="media-story-actions"><span class="pill">${candidates.length} ${selectedOnly?'selected':'results'}</span><button class="btn ${all.length?'secondary':'primary'} story-broll-btn" data-search-story-media="${group.story.id}">${all.length?'Regenerate B-roll':'Find B-roll'}</button></div></div>${(group.story.articles||[]).length?`<details class="story-source-details"><summary>News sources (${group.story.articles.length})</summary>${group.story.articles.map(a=>`<a href="${safeExternalUrl(a.url)}" target="_blank" rel="noreferrer">${esc(a.source||'Source')} — ${esc(a.title||'')}</a>`).join('')}</details>`:''}${(group.story.context_sources||[]).length?`<details class="story-source-details context-source-details"><summary>Fun-fact / visual-context sources (${group.story.context_sources.length})</summary>${group.story.context_sources.map(a=>`<a href="${safeExternalUrl(a.url)}" target="_blank" rel="noreferrer">${esc(a.source||'Source')} — ${esc(a.title||'')}</a>`).join('')}</details>`:''}${videos.length?`<div class="media-kind-title">Videos · ${videos.length}</div><div class="candidate-grid video-grid">${videos.map(mediaCandidateCard).join('')}</div>`:''}${images.length?`<div class="media-kind-title">${videos.length?'Supporting images':'Fallback images · no suitable HD official B-roll found'} · ${images.length}</div><div class="candidate-grid">${images.map(mediaCandidateCard).join('')}</div>`:''}${!candidates.length?'<div class="no-media">No suitable official B-roll or fallback images found for this story.</div>':''}</section>`}).join('')}</div>`}
function videoQualityLabel(item){const h=Number(item.height||0);if(item.media_type!=='video')return '';if(h>=2160)return '4K';if(h>=1440)return '1440p';if(h>=1080)return '1080p';if(h>=720)return '720p';if(h>0)return `${h}p`;return 'quality unknown'}
function imageQualityLabel(item){if(item.media_type!=='image')return '';const w=Number(item.width||0),h=Number(item.height||0);if(!w||!h)return 'dimensions unknown';const aspect=w/h;const orientation=aspect>=1.25?'Landscape':aspect<1?'Portrait':'Near-square';const uhd=w>=3200&&h>=1600?' · 4K-ready':w>=1920&&h>=1000?' · HD+':'';return `${w}×${h} · ${orientation}${uhd}`}
function imageQualityClass(item){if(item.media_type!=='image')return '';const w=Number(item.width||0),h=Number(item.height||0);if(!w||!h)return '';const aspect=w/h;const layout=String(item.layout_hint||'single');if(aspect<1.2&&['two_up','three_up','stacked_two','stacked_three','person_plus_title','collage'].includes(layout))return 'image-layout-ready';if(aspect<1.2)return 'image-warning';if(w>=3200&&h>=1600)return 'image-best';return ''}
function clipTime(sec){sec=Number(sec);if(!Number.isFinite(sec)||sec<0)return '';const m=Math.floor(sec/60),s=Math.floor(sec%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function clipRangeLabel(item){if(item.media_type!=='video'||item.clip_start_sec==null||item.clip_end_sec==null)return '';return `${clipTime(item.clip_start_sec)}–${clipTime(item.clip_end_sec)}`}
function mediaCandidateCard(item){const thumb=item.thumbnail_url||'';const status=item.download_status||'not_downloaded';const quality=videoQualityLabel(item);const imageQuality=imageQualityLabel(item);const imageClass=imageQualityClass(item);const clip=clipRangeLabel(item);const contextual=item.media_type==='video'&&String(item.provider||'').startsWith('Contextual B-roll');const rawSourceKind=item.media_type==='video'&&item.provider?.includes('·')?item.provider.split('·').slice(1).join('·').trim():'';const sourceKind=contextual&&rawSourceKind?`Contextual · ${rawSourceKind}`:rawSourceKind;const coverageLabel=String(item.coverage_label||'').trim();const coverageKind=String(item.coverage_kind||'').trim();const kindLabels={current:'Current title','cast/director':'Cast / director',person:'Person',related_title:'Related title',behind_the_scenes:'BTS / production',interview:'Interview',fun_fact:'Fun-fact shot',comparison:'Comparison',event_photo:'Event / red carpet','supporting image':'Supporting image'};const coverageKindText=kindLabels[coverageKind]||coverageKind.replaceAll('_',' ');const layout=String(item.layout_hint||'single');const cue=String(item.coverage_cue||'').trim();return `<article class="candidate-card ${item.selected?'selected':''}"><div class="candidate-preview">${thumb?`<img src="${safeExternalUrl(thumb)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.parentElement.classList.add('broken');this.remove()" />`:'<div class="preview-fallback">No preview</div>'}<span class="media-type-badge">${esc(item.media_type)}</span>${quality?`<span class="quality-badge">${esc(quality)}</span>`:''}${imageQuality?`<span class="quality-badge ${imageClass}">${esc(imageQuality)}</span>`:''}</div><div class="candidate-body"><strong title="${esc(item.title)}">${esc(item.title||'Untitled media')}</strong><small>${esc(item.source||item.provider||'Web source')}${item.duration?` · ${esc(item.duration)}`:''}${quality?` · ${esc(quality)}`:''}</small><div class="candidate-chips">${coverageLabel?`<span class="coverage-chip">Covers: ${esc(coverageLabel)}${coverageKindText?` · ${esc(coverageKindText)}`:''}</span>`:''}${layout!=='single'?`<span class="layout-chip">${esc(layout.replaceAll('_',' '))} layout</span>`:''}${sourceKind?`<span class="source-kind">${esc(sourceKind)}</span>`:''}${clip?`<span class="clip-range">Suggested clip ${esc(clip)}</span>`:''}${item.shared_source?`<span class="shared-source">Shared source · different segment</span>`:''}</div>${cue?`<div class="coverage-cue"><strong>Narration cue:</strong> ${esc(cue)}</div>`:''}<div class="candidate-status ${status}">${status==='downloaded'?'Downloaded ✓':status==='failed'?'Download failed':item.selected?'Selected':'Not selected'}</div>${item.error?`<div class="candidate-error">${esc(item.error)}</div>`:''}<div class="candidate-actions"><label class="select-toggle"><input type="checkbox" data-media-select="${item.id}" ${item.selected?'checked':''}/> Select</label><div class="candidate-link-row">${item.media_type==='image'&&item.asset_url?`<a class="btn ghost small-link" href="${safeExternalUrl(item.asset_url)}" target="_blank" rel="noreferrer">Open image</a>`:''}<a class="btn ghost small-link" href="${safeExternalUrl(item.page_url)}" target="_blank" rel="noreferrer">${item.media_type==='video'?'Open video':'Source page'}</a></div></div></div></article>`}
async function setMediaSelected(id,selected){try{await api(`/api/projects/${state.project.id}/media/candidates/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({selected})});const item=state.mediaGroups.flatMap(g=>g.candidates||[]).find(x=>x.id===id);if(item)item.selected=selected;state.project=await api(`/api/projects/${state.project.id}`);if(state.active===5)await renderStage()}catch(e){toast(e.message,true)}}
async function findMediaHtml(){const groups=await loadMediaGroups();const selected=groups.flatMap(g=>g.candidates||[]).filter(x=>x.selected);const downloaded=selected.filter(x=>x.download_status==='downloaded').length;const pending=selected.filter(x=>x.download_status!=='downloaded').length;const buttonText=downloaded&&pending?`Retry Failed / Pending (${pending})`:`Download Selected (${selected.length})`;return `<div class="section-head"><div><div class="eyebrow">STEP 06</div><h2>Selected downloads</h2><p>Review everything you selected in Media Sources, then download those files into this project's media folder.</p></div><button id="downloadSelectedBtn" class="btn primary" ${pending?'':'disabled'}>${buttonText}</button></div><div class="research-summary"><div class="metric card"><span>${selected.length}</span><small>selected</small></div><div class="metric card"><span>${downloaded}</span><small>downloaded</small></div><div class="metric card"><span>${selected.filter(x=>x.media_type==='image').length}</span><small>images</small></div><div class="metric card"><span>${selected.filter(x=>x.media_type==='video').length}</span><small>videos</small></div></div><div class="run-note">Downloads are saved under <code>media/selected/&lt;story&gt;/</code>. Already-downloaded selections are skipped on retry, so a partial failure only retries the remaining failed/pending assets. The app does not claim reuse rights; check licensing/permission for each selected asset before publishing.</div><div style="height:12px"></div>${selected.length?renderMediaGroups(groups,true):'<div class="card placeholder">Select images/videos in Step 5 first.</div>'}`}
async function downloadSelectedMedia(){const b=$('#downloadSelectedBtn');b.disabled=true;b.textContent='Downloading selected media…';const selectedItems=state.mediaGroups.flatMap(g=>g.candidates||[]).filter(x=>x.selected);const pending=selectedItems.filter(x=>x.download_status!=='downloaded').length;startRunStatus({title:'Downloading selected media',meta:`${pending||selectedItems.length} asset${(pending||selectedItems.length)===1?'':'s'} to process`,steps:['Request sent','Downloading highest quality','Saving project files','Downloads complete']});try{const r=await api(`/api/projects/${state.project.id}/media/download-selected`,{method:'POST'});state.project=await api(`/api/projects/${state.project.id}`);await renderStage();if(r.failed){finishRunStatusWarning(`${r.failed} download${r.failed===1?'':'s'} still failed. Already-downloaded files were kept; use Retry Failed / Pending to try only the remaining item(s). `,'Downloads finished with errors');toast(`Downloaded ${r.downloaded}; ${r.failed} failed. Open failed cards for details.`,true)}else{finishRunStatus(true,'','Selected media downloaded');toast(`Downloaded ${r.downloaded} selected media files`)}}catch(e){finishRunStatus(false,e.message);toast(e.message,true);if(b){b.disabled=false;b.textContent='Retry Failed / Pending'}}}

async function loadResolvePlan(){try{return await api(`/api/projects/${state.project.id}/resolve-plan`)}catch(e){return {ready:false,plan:null,files:[],message:e.message}}}
function resolveClipRow(item){const crop=item.crop||{};const sourceIn=item.original_source_in??item.source_in??0;const sourceOut=item.original_source_out??item.source_out??0;const source=item.media_type==='video'?`${voiceTime(sourceIn)}–${voiceTime(sourceOut)}`:'Still';const format=item.resolve_media_format?` · ${item.resolve_media_format}`:'';const coverage=item.coverage_label?`${item.coverage_label}${item.coverage_kind?` · ${String(item.coverage_kind).replaceAll('_',' ')}`:''}`:'';const layout=item.layout_hint&&item.layout_hint!=='single'?String(item.layout_hint).replaceAll('_',' '):'';return `<div class="resolve-clip"><div><span class="pill">${esc(item.media_type)}</span><strong>${esc(item.title||'Media')}</strong><small>${voiceTime(item.timeline_start)}–${voiceTime(item.timeline_end)} · ${Number(item.timeline_duration||0).toFixed(1)}s${coverage?` · ${esc(coverage)}`:''}</small></div><div class="resolve-clip-meta"><span>Source ${esc(source)}</span>${layout?`<span>Layout ${esc(layout)}</span>`:''}<span>${esc(crop.mode||'scale_full_frame_with_crop')}</span><span>${crop.crop_axis&&crop.crop_axis!=='none'?`Crop ${esc(crop.crop_axis)} ${Math.round(Number(crop.crop_fraction||0)*100)}%`:'16:9 / no crop'}</span><span>${esc(format)}</span></div></div>`}
function resolveMissingDetailsHtml(q){const details=q.missing_story_details||[];if(!details.length)return '';return `<div class="resolve-missing-list">${details.map(item=>{const segments=(item.segment_indexes||[]).join(', ');const title=item.title||'Unresolved narration story';const excerpt=String(item.narration_excerpt||'').trim();return `<div class="card resolve-missing-item"><strong>Missing mapping: ${esc(title)}</strong><small>${segments?`Voice segment(s): ${esc(segments)} · `:''}${esc(item.mapping_status||'unresolved')}</small>${excerpt?`<p>${esc(excerpt)}</p>`:''}</div>`}).join('')}</div>`}
async function resolvePlanHtml(){const data=await loadResolvePlan();const p=data.plan;const voiceStaleNote=data.voice_status?.stale?`<div class="run-note warn">⚠ ${esc(data.voice_status.message)}</div>`:'';if(!p){const q=data.prerequisites||{};const voiceTotal=Number(q.voice_total||0),voicePending=Number(q.voice_pending||0),voiceReady=Math.max(0,voiceTotal-voicePending),missingStories=(q.stories_missing_downloaded_media||[]).length,canGenerate=!!q.ready;const missingDetails=resolveMissingDetailsHtml(q);const reconcile=q.story_id_reconciliation||{};const mapped=Number(reconcile.remapped_segment_count||0);return `<div class="section-head"><div><div class="eyebrow">STEP 07</div><h2>DaVinci Resolve plan</h2><p>Build the edit only from the current approved ElevenLabs takes and the media downloaded in Step 6.</p></div><button id="generateResolveBtn" class="btn primary" ${canGenerate?'':'disabled'}>Generate Resolve Package</button></div>${voiceStaleNote}<div class="research-summary"><div class="metric card"><span>${voiceReady}/${voiceTotal}</span><small>approved voice segments</small></div><div class="metric card"><span>${Number(q.selected_downloaded||0)}</span><small>downloaded selected media</small></div><div class="metric card"><span>${missingStories}</span><small>stories missing media</small></div><div class="metric card"><span>${data.stale?'STALE':'—'}</span><small>previous package</small></div></div><div class="run-note">The voice track is the master timeline. Resolve generation stays locked until every narration segment has an approved aligned take and every narrated news story is matched to downloaded selected media.${mapped?` Automatically reconciled ${mapped} stale voice segment${mapped===1?'':'s'} to current stories.`:''}</div><div class="card placeholder">${esc(data.message||'Complete the prerequisites above, then generate the package.')}</div>${missingDetails}`};const files=(data.files||[]).map(x=>`<div class="resolve-file ${x.exists?'ready':''}"><strong>${esc(x.name)}</strong><span>${x.exists?fmt(x.size)+' bytes':'missing'}</span></div>`).join('');const warnings=(p.warnings||[]).map(x=>`<div class="run-note warn">${esc(x)}</div>`).join('');const clips=(p.visual_clips||[]).map(resolveClipRow).join('');return `<div class="section-head"><div><div class="eyebrow">STEP 07</div><h2>DaVinci Resolve plan</h2><p>Voice timing is authoritative. ElevenLabs word alignment now provides preferred visual beat points, so cuts follow narration phrases instead of a fixed timer. Trailer/clip scenes are then chosen from useful non-overlapping source ranges. Each still is used once for at most 3 seconds. Intro and outro are reserved with no news B-roll.</p></div><div class="top-actions"><button id="openResolveFolderBtn" class="btn ghost">Open Resolve Folder</button><button id="generateResolveBtn" class="btn primary">Regenerate Package</button></div></div>${voiceStaleNote}<div class="research-summary"><div class="metric card"><span>${voiceTime(p.timeline?.duration_seconds||0)}</span><small>episode voice duration</small></div><div class="metric card"><span>${p.visual_clips?.length||0}</span><small>visual cuts</small></div><div class="metric card"><span>${p.story_windows?.length||0}</span><small>voice windows</small></div><div class="metric card"><span>${p.fps||30}</span><small>fps · UHD</small></div></div><div class="run-note">Import the <strong>newly generated news_timeline.otio</strong> in Resolve. Trailer cuts use cached scene analysis plus ElevenLabs phrase timing. Repeated uses favor scenes from noticeably different parts of the source and keep taking genuinely different non-overlapping footage until the narration is covered or the source is actually exhausted. Low-variety logo/title-announcement footage is strongly deprioritized after its first use, but can supply a different unused range instead of leaving a news section black when it is the only selected video. Each still is used once for at most 3 seconds. Intro and outro stay reserved for your own visuals. Hard cuts are kept inside the same trailer; short dissolves are reserved for still/media/story changes. The package stages Resolve-safe H.264 media under <code>resolve/media/</code>.</div>${warnings}<div class="resolve-files">${files}</div><div class="media-kind-title">Planned visual cuts</div><div class="resolve-clip-list">${clips||'<div class="no-media">No visual clips were planned.</div>'}</div>`}
async function generateResolvePlan(){startRunStatus({title:'Building DaVinci Resolve package',meta:'Voice master timing · UHD 3840×2160',steps:['Validating aligned voice','Finding narration beat points','Analyzing trailer scenes','Selecting shots + transitions','Normalizing Resolve-safe media','Building OTIO package','Package saved']});try{const r=await api(`/api/projects/${state.project.id}/resolve-plan/generate`,{method:'POST'});state.project=await api(`/api/projects/${state.project.id}`);await renderStage();finishRunStatus(true,'','Resolve package generated');toast(r.warning_count?`Resolve package ready with ${r.warning_count} warning(s)`:'Resolve package ready')}catch(e){finishRunStatus(false,e.message);toast(e.message,true)}}
async function openResolveFolder(){try{await api(`/api/projects/${state.project.id}/resolve-plan/open-folder`,{method:'POST'})}catch(e){toast(e.message,true)}}

async function refreshSettings(){try{state.settings=await api('/api/settings')}catch(e){state.settings={ai:{}}}}
async function openSettings(){await refreshSettings();const a=state.settings.ai||{};$('#sResearchProvider').value=a.research_provider||'codex_local';$('#sResearchModel').value=a.research_model||'default';$('#sWriterProvider').value=a.writer_provider||'codex_local';$('#sWriterModel').value=a.writer_model||'default';$('#sReviewerProvider').value=a.reviewer_provider||'claude_local';$('#sReviewerModel').value=a.reviewer_model||'default';renderProviderStatus(state.settings.local_providers||{});$('#settingsDialog').showModal()}
function renderProviderStatus(p){$('#providerStatus').innerHTML=['codex_local','claude_local'].map(k=>{const x=p[k]||{};const ok=x.installed&&x.authenticated;return `<div class="provider-card"><strong class="${ok?'provider-ok':'provider-bad'}">${esc(x.label||k)} ${ok?'✓':''}</strong><small>${esc(x.version||'Not installed')}<br>${esc(x.message||'')}</small><div class="provider-actions"><button type="button" class="btn secondary" data-login="${k}">Sign in</button><button type="button" class="btn ghost" data-test="${k}">Test</button></div></div>`}).join('')}
async function providerLogin(provider){try{const r=await api('/api/local-providers/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider})});toast(r.message)}catch(e){toast(e.message,true)}}
async function providerTest(provider){try{const r=await api('/api/local-providers/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider})});toast(`${provider}: ${r.response}`)}catch(e){toast(e.message,true)}}
async function saveSettings(e){e.preventDefault();const body={research_provider:$('#sResearchProvider').value,research_model:$('#sResearchModel').value.trim()||'default',writer_provider:$('#sWriterProvider').value,writer_model:$('#sWriterModel').value.trim()||'default',reviewer_provider:$('#sReviewerProvider').value,reviewer_model:$('#sReviewerModel').value.trim()||'default',prefer_api_providers:false};try{await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#settingsDialog').close();await refreshSettings();toast('AI settings saved')}catch(err){toast(err.message,true)}}
async function saveApiKey(provider){const input=provider==='openai'?$('#openaiKey'):$('#anthropicKey');if(!input.value.trim())return toast('Paste a key first',true);try{await api('/api/settings/api-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,key:input.value.trim()})});input.value='';await refreshSettings();toast(`${provider} API key saved`)}catch(e){toast(e.message,true)}}

init().catch(e=>toast(e.message,true));

async function loadPronunciations(){try{return await api(`/api/pronunciations?language=${encodeURIComponent(state.project?.language||'Persian')}`)}catch(e){return {entries:[],text:''}}}
function pronunciationCardHtml(p){const count=(p?.entries||[]).length;return `<section class="card pronunciation-card"><div class="voice-config-head"><div><div class="eyebrow">PRONUNCIATION LIST · ${esc(state.project?.language||'')}</div><h3>${count} name${count===1?'':'s'} with vowel marks</h3><p>One per line: <code>written = pronounced</code>. The pronounced form may only add vowel marks (اعراب), so the approved words never change. Applied automatically when you Prepare v3 Performance, for every project in this language.</p></div></div><textarea id="pronunciationText" dir="${projectDir()}" rows="${Math.min(10,Math.max(3,count+2))}" placeholder="نام نوشته‌شده = نامِ اعراب‌گذاری‌شده">${esc(p?.text||'')}</textarea><div class="voice-actions"><button class="btn secondary" onclick="savePronunciations()">Save Pronunciation List</button></div></section>`}
async function savePronunciations(){const text=$('#pronunciationText')?.value||'';try{const r=await api('/api/pronunciations',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({language:state.project?.language||'Persian',text})});await renderStage();const bad=(r.rejected||[]);toast(bad.length?`Saved ${r.entries.length}; skipped ${bad.length}: ${bad[0]}`:`Saved ${r.entries.length} pronunciation${r.entries.length===1?'':'s'} · re-run Prepare v3 Performance to apply`,bad.length>0)}catch(e){toast(e.message,true)}}
